import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.yO0biSGH.js";const u=JSON.parse('{"title":"Go 教程重写设计：用连续讲解建立知识体系","description":"","frontmatter":{},"headers":[],"relativePath":"ryugi/specs/2026-11-05-go-tutorial-rewrite-design.md","filePath":"ryugi/specs/2026-11-05-go-tutorial-rewrite-design.md","lastUpdated":1793862325000}'),d={name:"ryugi/specs/2026-11-05-go-tutorial-rewrite-design.md"};function i(l,t,p,n,h,s){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="go-教程重写设计-用连续讲解建立知识体系" tabindex="-1">Go 教程重写设计：用连续讲解建立知识体系 <a class="header-anchor" href="#go-教程重写设计-用连续讲解建立知识体系" aria-label="Permalink to &quot;Go 教程重写设计：用连续讲解建立知识体系&quot;">​</a></h1><p>批准记录：用户已提交 design-approval-20261105，choice=approve。本次授权先准备 04 章覆盖清单与章级候选，不直接修改教程正文。Artifact 中原样稿与历史讨论继续保留。</p><blockquote><p>将重写的重点从“补齐条目”改为“读者能顺着例子解释机制”，但不以改善阅读为由删减正确知识。你的最新确认是：正文讲运行过程，汇编选读。当前没有启动批审或修改教程正文。</p></blockquote><h2 id="当前理解-事实、猜测与待确认" tabindex="-1">当前理解：事实、猜测与待确认 <a class="header-anchor" href="#当前理解-事实、猜测与待确认" aria-label="Permalink to &quot;当前理解：事实、猜测与待确认&quot;">​</a></h2><p>已知事实：你最初要解决的是语言风格与教学组织，而不只是补齐知识点。你要求范围涉及仓库内所有文档，参考已下载的教程；不希望把每节固定成一套表格模板，也明确否定过不利于人类阅读的机制对照表。现在你要求重新用 Ryugi 脑暴和 Artifact 讨论。</p><p>已有执行记录：上一阶段 TB29 K1-K14 已分两批落盘，批 2 的 run 为 handbook-batch-mw32ryu8-efq9zn。这证明该批经过条目双审，不证明全书语言风格已校准，也不证明 04 章所有来源、所有内容都已完成。</p><p>问题判断（我的判断）：事实覆盖与阅读体验是不同的验收维度。前期批审提供的事实证据继续保留，但不能替代对章节主线、衔接和机制解释的检查。</p><p>待批准：下面的完整方案，尤其是先完成 04 章试产、按知识单元推进其余文档，以及正文与出处记录的分工。这些推进安排是我的建议，不是此前样稿确认自动包含的授权。</p><h2 id="沿用的决定与本轮边界" tabindex="-1">沿用的决定与本轮边界 <a class="header-anchor" href="#沿用的决定与本轮边界" aria-label="Permalink to &quot;沿用的决定与本轮边界&quot;">​</a></h2><ul><li>你的要求：覆盖仓库内所有文档；实际改动按文档用途区分，不把教程讲法机械套进操作说明与索引。</li><li>你的要求：参考之前下载的教程，讲解要有体系、讲透机制；不靠悬念修辞，不以术语清单和表格代替推导。</li><li>我的决定：本轮只更新讨论材料，不改教程正文、不启动批审、不改台账。旧审稿与落盘回执原样保留。</li><li>你的选择（本轮提交）：先看一段完整讲解，校准讲法。该项按推荐提交；没有新增文字评论。</li><li>你的选择（第 2 轮提交）：候选讲法接近预期，沿这条讲解主线继续展开机制；该项按推荐提交，没有新增文字评论。尚未批准整章替换或全书统一模板。</li><li>你的选择（第 3 轮提交）：机制深度合适，正文解释过程、汇编选读；该项按推荐提交，没有新增文字评论。</li></ul><h2 id="一、目标-读者能跟着推导-不只是记住结论" tabindex="-1">一、目标：读者能跟着推导，不只是记住结论 <a class="header-anchor" href="#一、目标-读者能跟着推导-不只是记住结论" aria-label="Permalink to &quot;一、目标：读者能跟着推导，不只是记住结论&quot;">​</a></h2><p>面向已有 Java、TypeScript、Python 等语言经验、希望建立 Go 知识体系的开发者。读者读完一个连续主题，应能说清：代码要解决什么问题；具体发生了什么；为什么这样发生；何时使用，以及边界是什么。解释机制时讲到编译器或运行时实际承担的工作，但先让读者知道正在解释哪段代码。</p><p>这不是把所有文章写短，也不是增加“你”“我们”等口语词。改写可以增加必要篇幅；目标是减少上下文切换和推理跳步，让细节围绕主线展开。</p><h2 id="二、范围与不做的事" tabindex="-1">二、范围与不做的事 <a class="header-anchor" href="#二、范围与不做的事" aria-label="Permalink to &quot;二、范围与不做的事&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>处理方式</th><th>边界</th></tr></thead><tbody><tr><td>guide/handbook</td><td>作为连续学习主路径，按主题组织问题、例子、推导与机制</td><td>已审内容保留证据；改动后的正确性重新核对</td></tr><tr><td>notes</td><td>保留细节库职责，修复解释断裂、过时内容和与主线不一致之处</td><td>不直接复制整章手册；详细机制不能只剩术语或链接</td></tr><tr><td>docs</td><td>按现有规则同步源文档镜像；独立维护的读者页面单独检查</td><td>生成镜像不作为第二份独立改写稿</td></tr><tr><td>README、路线、索引、操作与贡献说明</td><td>按导航或操作用途改善信息组织、术语和链接</td><td>不强制使用故事、失败案例或运行时分析</td></tr><tr><td>下载教程与 work 原材料</td><td>作为事实核对与成品讲法的参照</td><td>不重写付费原件，不照搬段落，不把 PDF 或私有材料发布到站点</td></tr></tbody></table><p>不做：重设计站点界面、改业务代码、全库统一替换词语、删除来源链、为消除文章缺陷而重建一套批审平台。全库文档是总体范围，不是一次提交的范围；不能因为 04 章样稿认可就声称其他文档已经改好。</p><h2 id="三、写作方式-一条主线-按需要展开" tabindex="-1">三、写作方式：一条主线，按需要展开 <a class="header-anchor" href="#三、写作方式-一条主线-按需要展开" aria-label="Permalink to &quot;三、写作方式：一条主线，按需要展开&quot;">​</a></h2><p>先决定本段要让读者理解什么，再选择一个能承载这些问题的具体场景。保留现有好例子；同一主题尽量让代码逐步演进，每次说明沿用了什么、改了什么。代码前说观察目的，代码后给实际结果，再解释结果与机制。不为制造悬念而隐瞒答案，不刻意安排“撞墙”。</p><p>一般的讲解顺序是“任务与当前代码 → 需要改变的地方 → 一次改动 → 结果 → 因果 → 规则与边界”。这是写作选择，不是每节必须具备的栏目。速查、配置步骤、目录与源码分析可以采用不同结构，只要读者不需要自行补齐推理。</p><p>主线必要的解释必须留在正文；汇编、逐字段源码和复核证据可以选读。是否移入选读，要检查读者不展开它时能否理解主线，不能只因篇幅长就移走。第 2 轮把多方法声明放在展开区只是样稿选择，正式改写时仍逐项核查，不因此默许降级其他知识。</p><p>关系、状态与调用流程用图；确有比较价值的属性用表；因果解释用连续段落。没有“每节三件套”、固定类比次数或强制小结。先讲清机制，再决定排版。</p><h2 id="四、机制与跨语言对照的深度" tabindex="-1">四、机制与跨语言对照的深度 <a class="header-anchor" href="#四、机制与跨语言对照的深度" aria-label="Permalink to &quot;四、机制与跨语言对照的深度&quot;">​</a></h2><p>采用已确认的第 3 轮基准：沿着正在运行的代码区分编译期规则、运行时表示和方法调用，再解释优化可能改变什么。实现细节注明工具链版本，不能把本次汇编中的寄存器、偏移、符号名说成语言规范。</p><p>跨语言对照围绕同一个问题：读者在 Java 中已经理解什么，Go 保留了什么目标，改变了哪条关系或执行路径。04 章必须补齐 Java/Go 多态机制对照，但不沿用旧样张“Java 一律查 vtable”“成本同量级”等结论。正式候选需区分 Java 语言规则、JVM 字节码、所选 JVM 实现与 JIT 优化；实现层结论查对应版本的原始依据，示例与字节码实际验证，不编造性能结论。</p><p>我的选择：Java 作为 04 章主要对照背景，TS/Python 只在确实能解除误解时补充；不把三门语言逐项铺成大表。机制讲解服务 Go 主线，不把整章变成 JVM 专题。</p><h2 id="五、先完成-04-章试产-再扩展" tabindex="-1">五、先完成 04 章试产，再扩展 <a class="header-anchor" href="#五、先完成-04-章试产-再扩展" aria-label="Permalink to &quot;五、先完成 04 章试产，再扩展&quot;">​</a></h2><ol><li><p><strong>核对整章内容边界</strong></p><p>把当前 04 章各段、相关原材料、已经双审的条目与未审部分建立对应关系。覆盖方法、方法集合、接口、nil、比较与装箱、嵌入、组合、any 以及练习和项目连接，不能只拿 TB29 十四条代表全章。记录每条知识的条件、例子、异常分支和引用。</p></li><li><p><strong>写成连贯的章级候选</strong></p><p>沿已确认样稿的通知场景串联接口部分；方法、指针、嵌入与组合按其自身问题安排例子。可调整小节顺序，但须补足依赖说明。把类型断言、nil 陷阱、接收者规则等完整落在候选中，不以链接代替已有必要讲解。整章候选先放在同一讨论文档的后续修订中供你阅读，不直接覆盖源文件。</p></li><li><p><strong>同时验证教学与事实</strong></p><p>实际运行示例与失败案例，核对来源和版本。用独立忠实性审读查知识遗漏与归属，用只读候选的读者审读查解释能否自洽。再由你检查完整章节的阅读体验；机器两审与人的章级验收都需要，互不代替。</p></li><li><p><strong>通过门禁后落盘与发布检查</strong></p><p>guide/handbook 的正式改动按现有 handbook-batch 生成提案；只有 reviewed 才做 apply --check 与 apply，同一目标串行落盘。随后按源文件规则同步对应镜像，运行引用守卫、ESLint、文档构建并实际查看变更页面。验证通过后回填台账和场景，主仓与状态仓互引证据。</p></li><li><p><strong>按知识单元推进其余文档</strong></p><p>04 章通过后，先按读者依赖推进其余 handbook，同步处理该知识单元关联的 notes；README、路线与索引随依赖变化更新。每章开始时核对事实与欠账，不照抄 04 章结构。每章结束给出变更范围、验收证据和剩余问题，不用一个总百分比掩盖不同层面的完成状态。</p></li></ol><h2 id="六、完整性、出处与审读纪律" tabindex="-1">六、完整性、出处与审读纪律 <a class="header-anchor" href="#六、完整性、出处与审读纪律" aria-label="Permalink to &quot;六、完整性、出处与审读纪律&quot;">​</a></h2><p>每个改写主题维护“原知识 → 新落点 → 处理方式 → 验证依据”的覆盖清单。合并只用于确实重复的内容；删改错误或过时知识时说明证据与版本。替换例子必须保留旧例所展示的不同机制，正文不能退化为条目名称、参考链接或附录清单。</p><p>出处安排（我的选择，待整体批准）：保留可追溯的条目与页码，当前不删除正文现有来源标记、不修改引用守卫。新写讲解不反复插入“原课说”“全文唯一”等审计口吻；这些归属判断放到审读记录，需要限定历史版本时才在正文解释。完整章稿中给出清楚的来源说明，不假装 TB 编号是读者必须回看的学习材料。是否调整引注的站点视觉呈现不在本次范围。</p><p>不得手改 run 的 status、reviews、pass 或逐项证据来让提案通过。needs_rework 或 blocked 保持未完成；问题来自上下文缺失时，把真实前文加入新评审输入，让独立审稿人重新判断。无法复核的实测只说明来源与未验证项，不伪装成这轮亲自运行。</p><p>notes 不在现有 apply 工具允许的 target 范围内，不能硬套 handbook 回执。我的执行选择是：沿用现有来源清单、候选、忠实性与读者两种独立审读，取得完整逐项证据后，由主助手以当前文件版本和唯一 before/after 校验手工落盘，并在状态仓保存目标、版本、提案、两份审读结果与落盘记录；缺少这组证据就不标“已落盘(双审通过)”。只换措辞或改导航的变更不虚增原材料条目的已审进度，不为此改造批审程序。</p><h2 id="七、验收-四种证据分别交代" tabindex="-1">七、验收：四种证据分别交代 <a class="header-anchor" href="#七、验收-四种证据分别交代" aria-label="Permalink to &quot;七、验收：四种证据分别交代&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>通过标准</th><th>不能拿什么代替</th></tr></thead><tbody><tr><td>内容完整</td><td>覆盖清单逐项可追踪到新文，条件、反例、边界与机制均有落点</td><td>字数、关键词、引用数量</td></tr><tr><td>教学自洽</td><td>只读候选能解释任务、行为、原因、选择与边界；用户章级阅读认可</td><td>只给“看起来顺”的审稿结论</td></tr><tr><td>技术正确</td><td>示例、失败案例实际验证；实现与版本依据准确；两类独立审读有记录</td><td>编译成功或助手自己宣布通过</td></tr><tr><td>站点交付</td><td>源文与镜像一致、链接与引用有效、构建通过、实际页面可读</td><td>只改源 Markdown 或只给构建日志</td></tr></tbody></table><p>已知命令：python3 -I scripts/check-handbook-refs.py；对变更文件运行 npx eslint；pnpm run docs:build。镜像沿 scripts/mirror.sh 的标题 frontmatter 规则同步，只处理本轮变更文件，避免覆盖无关改动。章节时长、导航和交叉链接如受影响，同批更新。执行中不把未运行的验证写成通过。</p><h2 id="八、交付与授权边界" tabindex="-1">八、交付与授权边界 <a class="header-anchor" href="#八、交付与授权边界" aria-label="Permalink to &quot;八、交付与授权边界&quot;">​</a></h2><p>这是一个跨多篇文档的项目，先交付一个完整 04 章试产，不一次性铺开全库。章内选词、段落划分、具体例子与图表由执行者按上述标准决定；改变知识范围、弱化机制深度或取消用户章级验收，不由执行者自行决定。</p><p>你批准后，先把本方案保存到 docs/ryugi/specs/2026-11-05-go-tutorial-rewrite-design.md，再开展 04 章覆盖清单与章级候选。保存的是设计，不是直接应用现有样稿。只有整章候选经你验收并通过技术门禁，才修改教程正文。</p><p>本次 Artifact 记录：document/rewrite-style-clarify，路径 .ryugi/artifacts/document/rewrite-style-clarify/doc.xml，同一链接承载三轮讨论与本方案。第 2 轮确定连续叙事方向，第 3 轮确定机制正文与汇编选读的分工。旧 artboard/style-reference 仅作历史参照，不把旧 A/B 或旧技术表述当作本方案验收标准；后面的旧动态演示也不成为新实现依据。</p><p>设计可执行性检查：独立审阅者 DesignBuilderCheck 已只读检查正式方案，返回“没有重要未决问题”。此检查只说明执行者不缺少重大规划信息，不代表全章技术双审已完成，也不替代你的整体批准。</p><h2 id="本次批准与首个执行边界" tabindex="-1">本次批准与首个执行边界 <a class="header-anchor" href="#本次批准与首个执行边界" aria-label="Permalink to &quot;本次批准与首个执行边界&quot;">​</a></h2><p>批准来源：document/rewrite-style-clarify 的 design-approval-20261105。先保存本设计并制作完整 04 章候选，在同一 Artifact 交用户章级验收；到此暂停正文落盘。其后 handbook 批审、镜像与其他章节的执行仍受正文验收门禁约束。旧 2026-11-03/04 设计中的强制三件套、旧行号、引用命中数门禁与 Java 单一 vtable 等表述不覆盖本设计。</p>',42)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
